INSERT INTO recipes (id, slug, title, description, cuisine, cook_time_minutes, servings, difficulty, image_url, tags, source_type, source_reference, verification_state, version) VALUES
('imp-199ff78d3d8c8ab3', 'canh-bi-do-nau-tom-tuoi-ngot-nuoc', 'Canh bí đỏ nấu tôm tươi ngọt nước', 'Bí đỏ hầm mềm tan trong nước dùng tôm tươi ngọt tự nhiên, thêm hành lá thơm nhẹ, món canh dễ nấu cho bữa cơm gia đình miền Nam.', 'vietnamese', 25, 4, 'easy', '/frigo/illustrations/delicious-meal.png', '["Món canh","Nam Bộ","Bổ dưỡng","Cơm nhà"]', 'ai_generated', 'T14F project-original recipe generation batch t14f-pilot-30-v1', 'reviewed', 1),
('imp-ab36e38b07f3a57b', 'suon-non-kho-dua-chua-ngot-dam-vi', 'Sườn non kho dứa chua ngọt đậm vị', 'Sườn non kho mềm cùng dứa chín, nước kho sánh màu cánh gián hòa vị chua ngọt hài hòa, món mặn đưa cơm quen thuộc của gia đình miền Nam.', 'vietnamese', 50, 4, 'medium', '/frigo/illustrations/delicious-meal.png', '["Món kho","Nam Bộ","Chua ngọt","Đưa cơm"]', 'ai_generated', 'T14F project-original recipe generation batch t14f-pilot-30-v1', 'reviewed', 1),
('imp-26a36c69306143bc', 'tom-xao-bong-cai-xanh-toi-gion-ngot', 'Tôm xào bông cải xanh tỏi giòn ngọt', 'Tôm tươi săn chắc xào nhanh với bông cải xanh giòn xanh mướt, thơm tỏi phi, món xào nhanh gọn giữ trọn vị ngọt tự nhiên.', 'vietnamese', 15, 3, 'easy', '/frigo/illustrations/delicious-meal.png', '["Món xào","Hải sản","Dưới 20 phút","Healthy"]', 'ai_generated', 'T14F project-original recipe generation batch t14f-pilot-30-v1', 'reviewed', 1),
('imp-b87b71d57128cc07', 'ca-loc-chien-sa-ot-vang-gion', 'Cá lóc chiên sả ớt vàng giòn', 'Cá lóc cắt khúc ướp sả ớt băm rồi chiên vàng giòn lớp ngoài, thịt cá bên trong vẫn mềm ngọt, chấm nước mắm tỏi ớt rất hợp cơm.', 'vietnamese', 30, 4, 'medium', '/frigo/illustrations/delicious-meal.png', '["Món chiên","Cá tươi","Nam Bộ","Đưa cơm"]', 'ai_generated', 'T14F project-original recipe generation batch t14f-pilot-30-v1', 'reviewed', 1),
('imp-511a92d180408e0a', 'trung-hap-thit-bam-nam-huong-mem-min', 'Trứng hấp thịt bằm nấm hương mềm mịn', 'Trứng gà đánh tan với thịt bằm và nấm hương, hấp chín mềm mịn như tàu hũ, món hấp thanh đạm hợp cho cả trẻ em và người lớn tuổi.', 'vietnamese', 25, 3, 'easy', '/frigo/illustrations/delicious-meal.png', '["Món hấp","Trẻ em thích","Thanh đạm","Cơm nhà"]', 'ai_generated', 'T14F project-original recipe generation batch t14f-pilot-30-v1', 'reviewed', 1),
('imp-d02c9b83214f81be', 'goi-dua-leo-tom-thit-gion-mat', 'Gỏi dưa leo tôm thịt giòn mát', 'Dưa leo giòn mát trộn cùng tôm luộc, thịt ba chỉ thái mỏng và cà rốt bào sợi, nước trộn chua ngọt đậm đà, món khai vị giải ngán hiệu quả.', 'vietnamese', 25, 4, 'easy', '/frigo/illustrations/delicious-meal.png', '["Món nộm","Khai vị","Giải ngán","Nam Bộ"]', 'ai_generated', 'T14F project-original recipe generation batch t14f-pilot-30-v1', 'reviewed', 1),
('imp-9ae951bec7fbf21b', 'hu-tieu-xao-tom-gia-he-kieu-sai-gon', 'Hủ tiếu xào tôm giá hẹ kiểu Sài Gòn', 'Sợi hủ tiếu dai mềm xào cùng tôm tươi, giá đỗ giòn và hành lá, nêm xì dầu đậm đà theo phong cách hàng quán Sài Gòn.', 'vietnamese', 20, 3, 'easy', '/frigo/illustrations/delicious-meal.png', '["Món xào","Hủ tiếu","Dưới 20 phút","Sài Gòn"]', 'ai_generated', 'T14F project-original recipe generation batch t14f-pilot-30-v1', 'reviewed', 1),
('imp-5ab5c1053b7371f0', 'dau-phu-chien-sa-ot-chay-dam-da', 'Đậu phụ chiên sả ớt chay đậm đà', 'Đậu phụ chiên vàng rồi xóc cùng sả ớt băm phi thơm, nêm nước tương, món chay đơn giản nhưng đậm đà, ăn cùng cơm nóng rất hợp.', 'vietnamese', 20, 3, 'easy', '/frigo/illustrations/delicious-meal.png', '["Món chay","Đậu phụ","Dưới 20 phút","Tiết kiệm"]', 'ai_generated', 'T14F project-original recipe generation batch t14f-pilot-30-v1', 'reviewed', 1),
('imp-67054d03e5a5b011', 'chao-trung-ga-hanh-la-gung-am-bung', 'Cháo trứng gà hành lá gừng ấm bụng', 'Cháo trắng nấu nhuyễn, đánh trứng gà tan vào cháo nóng, thêm gừng thái sợi và hành lá, bữa sáng nhẹ nhàng dễ tiêu.', 'vietnamese', 20, 2, 'easy', '/frigo/illustrations/delicious-meal.png', '["Ăn sáng","Dưới 20 phút","Dễ tiêu","Ấm bụng"]', 'ai_generated', 'T14F project-original recipe generation batch t14f-pilot-30-v1', 'reviewed', 1),
('imp-e375595daced53af', 'lau-bo-nhung-dua-chua-thanh', 'Lẩu bò nhúng dứa chua thanh', 'Nước lẩu chua thanh từ dứa và cà chua, thơm sả, nhúng thịt bò thái mỏng chín tới cùng rau muống và bún, món lẩu gia đình dễ chuẩn bị.', 'vietnamese', 40, 4, 'medium', '/frigo/illustrations/delicious-meal.png', '["Món lẩu","Thịt bò","Cuối tuần","Nam Bộ"]', 'ai_generated', 'T14F project-original recipe generation batch t14f-pilot-30-v1', 'reviewed', 1),
('imp-9b4ea97916a44e67', 'canh-rau-muong-nau-tom-thanh-mat', 'Canh rau muống nấu tôm thanh mát', 'Rau muống xanh giòn nấu nhanh với tôm tươi giã nhuyễn, nước canh trong và ngọt thanh, món canh giải nhiệt mùa hè kiểu miền Bắc.', 'vietnamese', 15, 4, 'easy', '/frigo/illustrations/delicious-meal.png', '["Món canh","Miền Bắc","Dưới 20 phút","Thanh mát"]', 'ai_generated', 'T14F project-original recipe generation batch t14f-pilot-30-v1', 'reviewed', 1),
('imp-6d7fc503ade5df6e', 'thit-ba-chi-xao-sa-ot-kieu-mien-trung', 'Thịt ba chỉ xào sả ớt kiểu miền Trung', 'Thịt ba chỉ thái mỏng xào săn với sả ớt băm thơm nồng, nêm nước mắm đậm đà theo khẩu vị miền Trung, món mặn cực đưa cơm.', 'vietnamese', 20, 3, 'easy', '/frigo/illustrations/delicious-meal.png', '["Món xào","Miền Trung","Cay nồng","Đưa cơm"]', 'ai_generated', 'T14F project-original recipe generation batch t14f-pilot-30-v1', 'reviewed', 1),
('imp-364497296cfcf033', 'muc-nhoi-thit-hap-gung-hanh', 'Mực nhồi thịt hấp gừng hành', 'Mực ống nhồi thịt xay trộn nấm, hấp chín mềm cùng gừng và hành lá, giữ trọn vị ngọt tự nhiên của hải sản, thanh nhẹ mà đầy đặn.', 'vietnamese', 35, 4, 'medium', '/frigo/illustrations/delicious-meal.png', '["Món hấp","Hải sản","Đãi khách","Thanh đạm"]', 'ai_generated', 'T14F project-original recipe generation batch t14f-pilot-30-v1', 'reviewed', 1),
('imp-806780abda4b5205', 'com-chien-dua-tom-hai-san', 'Cơm chiên dứa tôm hải sản', 'Cơm chiên tơi hạt cùng tôm tươi, dứa chín ngọt và trứng gà, nêm nước mắm thơm lừng, bữa sáng nhanh gọn đầy màu sắc.', 'vietnamese', 20, 3, 'easy', '/frigo/illustrations/delicious-meal.png', '["Ăn sáng","Cơm chiên","Dưới 20 phút","Hải sản"]', 'ai_generated', 'T14F project-original recipe generation batch t14f-pilot-30-v1', 'reviewed', 1),
('imp-a48b19224e397cea', 'com-bo-hanh-tay-gyudon-kieu-nhat', 'Cơm bò hành tây Gyudon kiểu Nhật', 'Thịt bò thái mỏng và hành tây om trong nước sốt xì dầu ngọt nhẹ, rưới lên cơm nóng, món donburi quen thuộc của bữa trưa Nhật Bản.', 'japanese', 20, 2, 'easy', '/frigo/illustrations/delicious-meal.png', '["Nhật Bản","Cơm donburi","Dưới 20 phút","Thịt bò"]', 'ai_generated', 'T14F project-original recipe generation batch t14f-pilot-30-v1', 'reviewed', 1),
('imp-79819e1b0c75f4da', 'mi-udon-xao-thit-heo-bap-cai-yaki-udon', 'Mì udon xào thịt heo bắp cải Yaki udon', 'Sợi udon dai mềm xào cùng thịt ba chỉ, bắp cải và cà rốt, nêm xì dầu đậm đà, món mì xào nhanh gọn kiểu Nhật cho bữa tối bận rộn.', 'japanese', 20, 2, 'easy', '/frigo/illustrations/delicious-meal.png', '["Nhật Bản","Mì xào","Dưới 20 phút","Cơm nhà"]', 'ai_generated', 'T14F project-original recipe generation batch t14f-pilot-30-v1', 'reviewed', 1),
('imp-ac255bcc36d1324e', 'ca-hoi-ap-chao-sot-teriyaki-bong-dep', 'Cá hồi áp chảo sốt teriyaki bóng đẹp', 'Phi lê cá hồi áp chảo da giòn, rưới sốt teriyaki tự pha từ xì dầu và đường, vị mặn ngọt bóng đẹp, dùng với cơm trắng và rau luộc.', 'japanese', 20, 2, 'easy', '/frigo/illustrations/delicious-meal.png', '["Nhật Bản","Cá hồi","Dưới 20 phút","Bổ dưỡng"]', 'ai_generated', 'T14F project-original recipe generation batch t14f-pilot-30-v1', 'reviewed', 1),
('imp-bb07db73fb381724', 'dau-phu-lanh-hiyayakko-gung-hanh', 'Đậu phụ lạnh Hiyayakko gừng hành', 'Đậu phụ non ướp lạnh, rưới xì dầu, rắc gừng bào và hành lá, món khai vị Nhật mát lành cho ngày nóng, không cần nấu.', 'japanese', 10, 2, 'easy', '/frigo/illustrations/delicious-meal.png', '["Nhật Bản","Khai vị","Không cần nấu","Dưới 15 phút"]', 'ai_generated', 'T14F project-original recipe generation batch t14f-pilot-30-v1', 'reviewed', 1),
('imp-a9398d96945ba6f7', 'canh-kim-chi-dau-phu-thit-ba-chi-kimchi-jjigae', 'Canh kim chi đậu phụ thịt ba chỉ Kimchi jjigae', 'Kim chi chua lên men nấu cùng thịt ba chỉ và đậu phụ mềm, nước canh cay nồng đậm đà, món canh Hàn Quốc ấm bụng ngày lạnh.', 'korean', 30, 3, 'easy', '/frigo/illustrations/delicious-meal.png', '["Hàn Quốc","Món canh","Cay","Kim chi"]', 'ai_generated', 'T14F project-original recipe generation batch t14f-pilot-30-v1', 'reviewed', 1),
('imp-af8a9cdb17d5e9fd', 'bo-xao-bulgogi-hanh-tay-ca-rot', 'Bò xào Bulgogi hành tây cà rốt', 'Thịt bò thái mỏng ướp xì dầu, tỏi và đường rồi xào nhanh với hành tây, cà rốt, vị ngọt mặn đặc trưng Bulgogi, ăn kèm cơm hoặc cuốn rau.', 'korean', 25, 3, 'easy', '/frigo/illustrations/delicious-meal.png', '["Hàn Quốc","Thịt bò","Món xào","Được yêu thích"]', 'ai_generated', 'T14F project-original recipe generation batch t14f-pilot-30-v1', 'reviewed', 1),
('imp-d3d0c59e0cfa845d', 'banh-kim-chi-chien-kimchi-jeon-gion-rum', 'Bánh kim chi chiên Kimchi jeon giòn rụm', 'Kim chi băm nhỏ trộn bột và trứng, chiên mỏng giòn cạnh, món bánh Hàn Quốc dân dã tận dụng kim chi chua, chấm xì dầu giấm.', 'korean', 20, 2, 'easy', '/frigo/illustrations/delicious-meal.png', '["Hàn Quốc","Ăn vặt","Kim chi","Dưới 20 phút"]', 'ai_generated', 'T14F project-original recipe generation batch t14f-pilot-30-v1', 'reviewed', 1),
('imp-262caf09e6f38c59', 'bong-cai-xanh-xao-toi-kieu-quang-dong', 'Bông cải xanh xào tỏi kiểu Quảng Đông', 'Bông cải xanh chần xanh giòn rồi xào nhanh với tỏi và gừng, nêm xì dầu nhẹ, món rau đơn giản trong bữa cơm gia đình Trung Hoa.', 'chinese', 15, 3, 'easy', '/frigo/illustrations/delicious-meal.png', '["Trung Hoa","Rau củ","Dưới 20 phút","Healthy"]', 'ai_generated', 'T14F project-original recipe generation batch t14f-pilot-30-v1', 'reviewed', 1),
('imp-352999f711c710d9', 'ga-xao-gung-hanh-kieu-quang-dong', 'Gà xào gừng hành kiểu Quảng Đông', 'Đùi gà lọc xương thái miếng xào với nhiều gừng và hành lá, nêm xì dầu, món gà thơm nồng đặc trưng ẩm thực Quảng Đông.', 'chinese', 25, 3, 'easy', '/frigo/illustrations/delicious-meal.png', '["Trung Hoa","Thịt gà","Món xào","Cơm nhà"]', 'ai_generated', 'T14F project-original recipe generation batch t14f-pilot-30-v1', 'reviewed', 1),
('imp-b3f99919ea9f17f8', 'canh-bi-dao-thit-bam-kieu-hoa', 'Canh bí đao thịt bằm kiểu Hoa', 'Bí đao nấu mềm trong nước dùng thịt bằm viên nhỏ, thêm gừng và hành lá, món canh thanh nhẹ giải nhiệt trong bữa cơm Trung Hoa.', 'chinese', 25, 4, 'easy', '/frigo/illustrations/delicious-meal.png', '["Trung Hoa","Món canh","Thanh mát","Cơm nhà"]', 'ai_generated', 'T14F project-original recipe generation batch t14f-pilot-30-v1', 'reviewed', 1),
('imp-b6dae711698259d6', 'canh-tom-chua-cay-tom-yum-kieu-thai', 'Canh tôm chua cay Tom Yum kiểu Thái', 'Nước dùng sả thơm nồng nấu cùng tôm tươi, nấm và cà chua, nêm nước mắm, chanh và ớt, vị chua cay đặc trưng của Thái Lan.', 'thai', 25, 3, 'medium', '/frigo/illustrations/delicious-meal.png', '["Thái Lan","Món canh","Chua cay","Hải sản"]', 'ai_generated', 'T14F project-original recipe generation batch t14f-pilot-30-v1', 'reviewed', 1),
('imp-f729957329cd75f5', 'mi-xao-pad-thai-tom-gia-do', 'Mì xào Pad Thai tôm giá đỗ', 'Sợi mì gạo xào cùng tôm, trứng và giá đỗ, nước sốt nước mắm chua ngọt, vắt chanh khi ăn, món mì xào quốc dân của Thái Lan.', 'thai', 25, 2, 'medium', '/frigo/illustrations/delicious-meal.png', '["Thái Lan","Mì xào","Hải sản","Được yêu thích"]', 'ai_generated', 'T14F project-original recipe generation batch t14f-pilot-30-v1', 'reviewed', 1),
('imp-04d0b94d17ce080c', 'ga-xao-gung-nam-kieu-thai-gai-pad-khing', 'Gà xào gừng nấm kiểu Thái Gai pad khing', 'Ức gà thái miếng xào với gừng thái sợi, nấm và hành tây, nêm xì dầu và ớt, món xào nhanh đậm hương gừng đặc trưng Thái Lan.', 'thai', 20, 3, 'easy', '/frigo/illustrations/delicious-meal.png', '["Thái Lan","Thịt gà","Dưới 20 phút","Món xào"]', 'ai_generated', 'T14F project-original recipe generation batch t14f-pilot-30-v1', 'reviewed', 1),
('imp-b01569fd0df22f66', 'mi-y-aglio-e-olio-toi-ot-dau-olive', 'Mì Ý Aglio e Olio tỏi ớt dầu olive', 'Spaghetti trộn với dầu olive, tỏi lát phi vàng và ớt, món pasta tối giản của Ý chỉ với vài nguyên liệu nhưng thơm ngon bất ngờ.', 'italian', 15, 2, 'easy', '/frigo/illustrations/delicious-meal.png', '["Ý","Pasta","Dưới 20 phút","Tối giản"]', 'ai_generated', 'T14F project-original recipe generation batch t14f-pilot-30-v1', 'reviewed', 1),
('imp-d463228be1e6e7c0', 'com-risotto-nam-bo-pho-mai-beo-ngay', 'Cơm Risotto nấm bơ phô mai béo ngậy', 'Gạo om từ từ với nước dùng, nấm xào thơm, kết thúc bằng bơ và phô mai bào tạo độ béo mịn, món cơm Ý ấm áp cho bữa tối.', 'italian', 40, 3, 'medium', '/frigo/illustrations/delicious-meal.png', '["Ý","Cơm risotto","Nấm","Béo ngậy"]', 'ai_generated', 'T14F project-original recipe generation batch t14f-pilot-30-v1', 'reviewed', 1),
('imp-9d575ec5c01896f0', 'mi-y-sot-kem-ca-hoi-rau-bina', 'Mì Ý sốt kem cá hồi rau bina', 'Spaghetti hòa cùng sốt kem sữa béo nhẹ, cá hồi áp chảo tách miếng và rau bina xanh mềm, món pasta thanh lịch cho bữa tối cuối tuần.', 'italian', 30, 3, 'medium', '/frigo/illustrations/delicious-meal.png', '["Ý","Pasta","Cá hồi","Cuối tuần"]', 'ai_generated', 'T14F project-original recipe generation batch t14f-pilot-30-v1', 'reviewed', 1);
