('imp-b01569fd0df22f66_ing_1', 'imp-b01569fd0df22f66', 'SPAGHETTI_PASTA', 'Mì spaghetti', 200, 'g', 0),
('imp-b01569fd0df22f66_ing_2', 'imp-b01569fd0df22f66', 'GARLIC', 'Tỏi', 2, 'piece', 0),
('imp-b01569fd0df22f66_ing_3', 'imp-b01569fd0df22f66', 'CHILI', 'Ớt', 1, 'piece', 0),
('imp-b01569fd0df22f66_ing_4', 'imp-b01569fd0df22f66', 'COOKING_OIL', 'Dầu olive', 50, 'ml', 0),
('imp-d463228be1e6e7c0_ing_1', 'imp-d463228be1e6e7c0', 'RICE', 'Gạo', 300, 'g', 0),
('imp-d463228be1e6e7c0_ing_2', 'imp-d463228be1e6e7c0', 'MUSHROOM', 'Nấm', 250, 'g', 0),
('imp-d463228be1e6e7c0_ing_3', 'imp-d463228be1e6e7c0', 'ONION', 'Hành tây', 1, 'piece', 0),
('imp-d463228be1e6e7c0_ing_4', 'imp-d463228be1e6e7c0', 'GARLIC', 'Tỏi', 1, 'piece', 0),
('imp-d463228be1e6e7c0_ing_5', 'imp-d463228be1e6e7c0', 'BUTTER', 'Bơ', 40, 'g', 0),
('imp-d463228be1e6e7c0_ing_6', 'imp-d463228be1e6e7c0', 'CHEDDAR_CHEESE', 'Phô mai bào', 60, 'g', 0),
('imp-9d575ec5c01896f0_ing_1', 'imp-9d575ec5c01896f0', 'SPAGHETTI_PASTA', 'Mì spaghetti', 300, 'g', 0),
('imp-9d575ec5c01896f0_ing_2', 'imp-9d575ec5c01896f0', 'SALMON_FILLET', 'Phi lê cá hồi', 300, 'g', 0),
('imp-9d575ec5c01896f0_ing_3', 'imp-9d575ec5c01896f0', 'SPINACH', 'Rau bina', 150, 'g', 0),
('imp-9d575ec5c01896f0_ing_4', 'imp-9d575ec5c01896f0', 'FRESH_MILK', 'Sữa tươi không đường', 250, 'ml', 0),
('imp-9d575ec5c01896f0_ing_5', 'imp-9d575ec5c01896f0', 'GARLIC', 'Tỏi', 1, 'piece', 0),
('imp-9d575ec5c01896f0_ing_6', 'imp-9d575ec5c01896f0', 'BUTTER', 'Bơ', 30, 'g', 0),
('imp-9d575ec5c01896f0_ing_7', 'imp-9d575ec5c01896f0', 'ONION', 'Hành tây', 0.5, 'piece', 0);
INSERT INTO recipe_steps (id, recipe_id, step_number, instruction, tip, timer_minutes) VALUES
('imp-199ff78d3d8c8ab3_step_1', 'imp-199ff78d3d8c8ab3', 1, 'Bí đỏ gọt vỏ, bỏ hạt, cắt miếng vuông 3cm. Tôm bóc vỏ, rút chỉ đen, ướp với chút muối và tiêu.', NULL, NULL),
('imp-199ff78d3d8c8ab3_step_2', 'imp-199ff78d3d8c8ab3', 2, 'Phi thơm tỏi băm với dầu ăn, cho tôm vào xào săn khoảng 1 phút rồi trút ra bát.', NULL, 1),
('imp-199ff78d3d8c8ab3_step_3', 'imp-199ff78d3d8c8ab3', 3, 'Cho bí đỏ vào nồi cùng 1 lít nước, đun sôi rồi hạ lửa nấu đến khi bí mềm.', NULL, 12),
('imp-199ff78d3d8c8ab3_step_4', 'imp-199ff78d3d8c8ab3', 4, 'Cho tôm trở lại nồi, nêm nước mắm, chút đường và muối cho vừa miệng, đun thêm 2 phút.', NULL, NULL),
('imp-199ff78d3d8c8ab3_step_5', 'imp-199ff78d3d8c8ab3', 5, 'Tắt bếp, rắc hành lá cắt nhỏ và tiêu xay, múc ra tô dùng nóng với cơm.', 'Không nấu bí quá lâu sau khi cho tôm để miếng bí giữ được hình dạng.', NULL),
('imp-ab36e38b07f3a57b_step_1', 'imp-ab36e38b07f3a57b', 1, 'Sườn non chặt khúc vừa ăn, chần qua nước sôi có chút muối rồi rửa sạch, để ráo.', NULL, NULL),
('imp-ab36e38b07f3a57b_step_2', 'imp-ab36e38b07f3a57b', 2, 'Ướp sườn với nước mắm, 1 thìa đường, tỏi băm, tiêu và hành tím băm trong 20 phút.', NULL, NULL),
('imp-ab36e38b07f3a57b_step_3', 'imp-ab36e38b07f3a57b', 3, 'Đun dầu ăn với 1 thìa đường đến khi chuyển màu cánh gián thì cho sườn vào đảo săn.', NULL, 5),
('imp-ab36e38b07f3a57b_step_4', 'imp-ab36e38b07f3a57b', 4, 'Thêm nước sôi ngang mặt sườn, cho dứa cắt miếng và ớt vào, kho lửa nhỏ đến khi sườn mềm và nước kho sánh lại.', 'Kho không đậy nắp để nước kho trong và bám đều miếng sườn.', 30),
('imp-ab36e38b07f3a57b_step_5', 'imp-ab36e38b07f3a57b', 5, 'Nêm lại cho vừa miệng, rắc tiêu và dùng nóng với cơm trắng.', NULL, NULL),
('imp-26a36c69306143bc_step_1', 'imp-26a36c69306143bc', 1, 'Tôm bóc vỏ, rút chỉ đen, ướp chút muối và tiêu. Bông cải xanh tách nhánh nhỏ, ngâm nước muối loãng rồi rửa sạch.', NULL, NULL),
('imp-26a36c69306143bc_step_2', 'imp-26a36c69306143bc', 2, 'Chần bông cải trong nước sôi có chút muối 1 phút rồi vớt ra ngâm nước lạnh để giữ màu xanh.', NULL, 1),
('imp-26a36c69306143bc_step_3', 'imp-26a36c69306143bc', 3, 'Phi thơm tỏi băm với dầu ăn, cho tôm vào xào lửa lớn đến khi tôm chuyển màu hồng.', NULL, NULL),
('imp-26a36c69306143bc_step_4', 'imp-26a36c69306143bc', 4, 'Cho bông cải vào xào cùng, nêm nước mắm và chút đường, đảo nhanh 2 phút rồi tắt bếp.', 'Xào lửa lớn và nhanh tay để bông cải giữ độ giòn.', 2),
('imp-b87b71d57128cc07_step_1', 'imp-b87b71d57128cc07', 1, 'Cá lóc làm sạch, cắt khúc dày 3cm, khứa nhẹ hai mặt và để ráo.', NULL, NULL),
('imp-b87b71d57128cc07_step_2', 'imp-b87b71d57128cc07', 2, 'Sả, ớt, tỏi băm nhuyễn; ướp cá với hỗn hợp này cùng chút muối, bột nghệ và tiêu trong 15 phút.', NULL, NULL),
('imp-b87b71d57128cc07_step_3', 'imp-b87b71d57128cc07', 3, 'Đun nóng dầu ăn trong chảo sâu, cho cá vào chiên lửa vừa mỗi mặt đến khi vàng giòn.', 'Lau khô cá trước khi chiên để dầu không bắn và da cá giòn hơn.', 10),
('imp-b87b71d57128cc07_step_4', 'imp-b87b71d57128cc07', 4, 'Vớt cá ra giấy thấm dầu. Pha nước mắm với chút đường, tỏi ớt băm và vài giọt nước cốt chanh để chấm.', NULL, NULL),
('imp-b87b71d57128cc07_step_5', 'imp-b87b71d57128cc07', 5, 'Xếp cá ra đĩa, rắc phần sả ớt còn lại đã phi vàng lên trên, dùng nóng với cơm.', NULL, NULL),
('imp-511a92d180408e0a_step_1', 'imp-511a92d180408e0a', 1, 'Nấm hương ngâm mềm, cắt hạt lựu. Thịt xay ướp với nước mắm, tiêu và hành lá cắt nhỏ.', NULL, NULL),
('imp-511a92d180408e0a_step_2', 'imp-511a92d180408e0a', 2, 'Đánh tan trứng với 150ml nước ấm và chút muối, lọc qua rây cho mịn rồi trộn cùng thịt và nấm.', NULL, NULL),
('imp-511a92d180408e0a_step_3', 'imp-511a92d180408e0a', 3, 'Đổ hỗn hợp vào bát chịu nhiệt, đậy màng bọc hoặc đĩa, hấp lửa vừa đến khi trứng đông hoàn toàn.', 'Hấp lửa vừa và đậy kín để mặt trứng không bị rỗ.', 15),
('imp-511a92d180408e0a_step_4', 'imp-511a92d180408e0a', 4, 'Rắc hành lá và tiêu lên mặt, rưới vài giọt nước mắm, dùng nóng với cơm.', NULL, NULL),
('imp-d02c9b83214f81be_step_1', 'imp-d02c9b83214f81be', 1, 'Luộc thịt ba chỉ chín, để nguội rồi thái lát mỏng. Tôm luộc chín, bóc vỏ, chẻ đôi.', NULL, 15),
('imp-d02c9b83214f81be_step_2', 'imp-d02c9b83214f81be', 2, 'Dưa leo bỏ ruột, thái lát chéo; cà rốt bào sợi. Ướp rau với chút muối 10 phút rồi vắt nhẹ cho ráo.', NULL, NULL),
('imp-d02c9b83214f81be_step_3', 'imp-d02c9b83214f81be', 3, 'Pha nước trộn: nước mắm, 2 thìa đường, nước cốt chanh, tỏi ớt băm, khuấy tan.', NULL, NULL),
('imp-d02c9b83214f81be_step_4', 'imp-d02c9b83214f81be', 4, 'Trộn dưa leo, cà rốt, tôm, thịt với nước trộn, để thấm 5 phút rồi bày ra đĩa, rắc rau răm và đậu phộng rang nếu có.', NULL, NULL),
('imp-9ae951bec7fbf21b_step_1', 'imp-9ae951bec7fbf21b', 1, 'Hủ tiếu trụng sơ nước sôi, xả nhanh và để ráo. Tôm bóc vỏ, ướp chút muối tiêu.', NULL, NULL),
('imp-9ae951bec7fbf21b_step_2', 'imp-9ae951bec7fbf21b', 2, 'Phi thơm tỏi với dầu ăn, xào tôm săn rồi trút ra để riêng.', NULL, NULL),
('imp-9ae951bec7fbf21b_step_3', 'imp-9ae951bec7fbf21b', 3, 'Cho hủ tiếu vào chảo, rưới xì dầu và chút dầu hào nếu có, đảo nhanh trên lửa lớn cho sợi thấm đều.', NULL, 3),
('imp-9ae951bec7fbf21b_step_4', 'imp-9ae951bec7fbf21b', 4, 'Cho tôm, giá đỗ và hành lá cắt khúc vào đảo thêm 1 phút, nêm vừa miệng, rắc tiêu và dùng nóng.', NULL, NULL),
('imp-5ab5c1053b7371f0_step_1', 'imp-5ab5c1053b7371f0', 1, 'Đậu phụ cắt miếng vuông vừa ăn, thấm khô bằng khăn sạch.', NULL, NULL),
('imp-5ab5c1053b7371f0_step_2', 'imp-5ab5c1053b7371f0', 2, 'Chiên đậu phụ trong dầu nóng đến khi vàng giòn các mặt, vớt ra để ráo.', NULL, 8),
('imp-5ab5c1053b7371f0_step_3', 'imp-5ab5c1053b7371f0', 3, 'Sả, ớt, tỏi băm nhuyễn; phi thơm với ít dầu còn lại trong chảo.', NULL, NULL),
('imp-5ab5c1053b7371f0_step_4', 'imp-5ab5c1053b7371f0', 4, 'Cho đậu phụ trở lại chảo, rưới nước tương pha với chút đường, xóc đều cho thấm rồi tắt bếp.', NULL, NULL),
('imp-5ab5c1053b7371f0_step_5', 'imp-5ab5c1053b7371f0', 5, 'Bày ra đĩa, rắc thêm sả ớt phi và tiêu, dùng nóng.', NULL, NULL),
('imp-67054d03e5a5b011_step_1', 'imp-67054d03e5a5b011', 1, 'Vo gạo, cho vào nồi với 1 lít nước, đun sôi rồi hạ lửa nhỏ nấu nhừ.', NULL, NULL),
('imp-67054d03e5a5b011_step_2', 'imp-67054d03e5a5b011', 2, 'Khuấy đều thường xuyên để cháo không dính đáy nồi và sánh mịn.', NULL, 15),
('imp-67054d03e5a5b011_step_3', 'imp-67054d03e5a5b011', 3, 'Đánh tan trứng, đổ từ từ vào cháo đang sôi nhẹ, khuấy nhanh cho trứng tan thành vân.', NULL, NULL),
('imp-67054d03e5a5b011_step_4', 'imp-67054d03e5a5b011', 4, 'Nêm nước mắm, chút muối, thêm gừng thái sợi và hành lá cắt nhỏ, rắc tiêu và dùng nóng.', NULL, NULL),
('imp-e375595daced53af_step_1', 'imp-e375595daced53af', 1, 'Thịt bò thái lát mỏng, ướp chút gừng, tỏi băm và tiêu. Rau muống nhặt ngọn, rửa sạch.', NULL, NULL),
('imp-e375595daced53af_step_2', 'imp-e375595daced53af', 2, 'Dứa cắt miếng, cà chua cắt múi cau, sả đập dập cắt khúc.', NULL, NULL),
('imp-e375595daced53af_step_3', 'imp-e375595daced53af', 3, 'Đun sôi 2 lít nước với sả, cho dứa và cà chua vào nấu 15 phút cho nước ngọt chua tự nhiên.', NULL, 15),
('imp-e375595daced53af_step_4', 'imp-e375595daced53af', 4, 'Nêm nước mắm, chút đường, muối và ớt cho vừa vị chua ngọt cay nhẹ.', NULL, NULL),
('imp-e375595daced53af_step_5', 'imp-e375595daced53af', 5, 'Bày thịt bò, rau, bún ra bàn; khi ăn nhúng thịt và rau vào nước lẩu sôi, ăn kèm bún và nước mắm ớt.', NULL, NULL),
('imp-9b4ea97916a44e67_step_1', 'imp-9b4ea97916a44e67', 1, 'Rau muống nhặt bỏ lá già, cắt khúc 5cm, rửa sạch. Tôm bóc vỏ, giã dập với chút muối.', NULL, NULL),
('imp-9b4ea97916a44e67_step_2', 'imp-9b4ea97916a44e67', 2, 'Phi thơm tỏi băm với chút dầu, cho tôm vào xào săn rồi thêm 1 lít nước, đun sôi.', NULL, NULL),
('imp-9b4ea97916a44e67_step_3', 'imp-9b4ea97916a44e67', 3, 'Cho rau muống vào, nấu sôi lại khoảng 3 phút cho rau vừa chín tới.', 'Không đậy nắp để rau giữ được màu xanh.', 3),
('imp-9b4ea97916a44e67_step_4', 'imp-9b4ea97916a44e67', 4, 'Nêm nước mắm và chút muối, tắt bếp, có thể vắt thêm chanh khi ăn.', NULL, NULL),
('imp-6d7fc503ade5df6e_step_1', 'imp-6d7fc503ade5df6e', 1, 'Thịt ba chỉ thái lát mỏng vừa ăn, ướp với nước mắm, chút đường và tiêu trong 10 phút.', NULL, NULL),
('imp-6d7fc503ade5df6e_step_2', 'imp-6d7fc503ade5df6e', 2, 'Sả bóc lớp vỏ già, cùng ớt và tỏi băm thật nhuyễn để dậy mùi khi xào.', NULL, NULL),
('imp-6d7fc503ade5df6e_step_3', 'imp-6d7fc503ade5df6e', 3, 'Cho thịt vào chảo nóng, xào lửa lớn đến khi thịt ra mỡ và xém vàng cạnh.', NULL, 6),
('imp-6d7fc503ade5df6e_step_4', 'imp-6d7fc503ade5df6e', 4, 'Cho sả ớt tỏi vào đảo cùng đến khi dậy mùi thơm, nêm lại cho vừa miệng.', NULL, NULL),
('imp-6d7fc503ade5df6e_step_5', 'imp-6d7fc503ade5df6e', 5, 'Thêm hành lá cắt khúc, đảo nhanh rồi tắt bếp, dùng nóng với cơm.', NULL, NULL),
('imp-364497296cfcf033_step_1', 'imp-364497296cfcf033', 1, 'Mực làm sạch, giữ nguyên thân ống, râu mực băm nhỏ. Nấm ngâm mềm, cắt hạt lựu.', NULL, NULL),
('imp-364497296cfcf033_step_2', 'imp-364497296cfcf033', 2, 'Trộn thịt xay với râu mực, nấm, hành lá băm, nước mắm và tiêu; nhồi vào thân mực, dùng tăm ghim miệng.', NULL, NULL),
('imp-364497296cfcf033_step_3', 'imp-364497296cfcf033', 3, 'Xếp mực lên đĩa, rải gừng thái sợi, hấp lửa lớn đến khi mực chín và nhân săn lại.', 'Không nhồi quá chặt để mực không bị nứt khi hấp.', 15),
('imp-364497296cfcf033_step_4', 'imp-364497296cfcf033', 4, 'Lấy ra, cắt khoanh vừa ăn, rưới nước hấp và rắc hành lá, chấm nước mắm gừng.', NULL, NULL),
('imp-806780abda4b5205_step_1', 'imp-806780abda4b5205', 1, 'Tôm bóc vỏ, cắt hạt lựu. Dứa cắt hạt lựu. Cơm nguội bóp tơi.', NULL, NULL),
('imp-806780abda4b5205_step_2', 'imp-806780abda4b5205', 2, 'Phi thơm hành lá phần đầu trắng với dầu, cho tôm xào săn rồi đổ trứng vào đảo tơi.', NULL, NULL),
('imp-806780abda4b5205_step_3', 'imp-806780abda4b5205', 3, 'Cho cơm vào xào lửa lớn, đảo đều đến khi hạt cơm săn và tơi.', NULL, 5),
('imp-806780abda4b5205_step_4', 'imp-806780abda4b5205', 4, 'Thêm dứa, nêm nước mắm và chút tiêu, đảo thêm 1 phút; rắc hành lá và dùng nóng.', NULL, NULL),
('imp-a48b19224e397cea_step_1', 'imp-a48b19224e397cea', 1, 'Nấu cơm. Hành tây thái múi mỏng, gừng thái sợi, thịt bò thái lát thật mỏng.', NULL, NULL),
('imp-a48b19224e397cea_step_2', 'imp-a48b19224e397cea', 2, 'Đun 200ml nước với xì dầu, 1 thìa đường và chút rượu mirin nếu có, cho hành tây vào nấu mềm.', NULL, 5),
('imp-a48b19224e397cea_step_3', 'imp-a48b19224e397cea', 3, 'Cho thịt bò và gừng vào, nấu lửa vừa đến khi thịt vừa chín, vớt bọt.', NULL, 4),
('imp-a48b19224e397cea_step_4', 'imp-a48b19224e397cea', 4, 'Múc cơm ra tô, xếp thịt bò và hành tây lên trên, rưới nước sốt, rắc hành lá và tiêu.', NULL, NULL),
('imp-79819e1b0c75f4da_step_1', 'imp-79819e1b0c75f4da', 1, 'Trụng mì udon trong nước sôi 1 phút, xả nước và để ráo. Thịt ba chỉ thái mỏng, bắp cải thái sợi, cà rốt thái que.', NULL, NULL),
('imp-79819e1b0c75f4da_step_2', 'imp-79819e1b0c75f4da', 2, 'Xào thịt ba chỉ với dầu đến khi xém vàng, cho cà rốt và bắp cải vào xào mềm.', NULL, 5),
('imp-79819e1b0c75f4da_step_3', 'imp-79819e1b0c75f4da', 3, 'Cho mì vào chảo, rưới xì dầu và chút dầu hào, đảo trên lửa lớn cho sợi mì thấm đều.', NULL, 3),
('imp-79819e1b0c75f4da_step_4', 'imp-79819e1b0c75f4da', 4, 'Rắc hành lá, tiêu, đảo đều rồi dọn ra đĩa dùng nóng.', NULL, NULL),
('imp-ac255bcc36d1324e_step_1', 'imp-ac255bcc36d1324e', 1, 'Cá hồi thấm khô, ướp chút muối tiêu. Pha sốt: xì dầu, 1 thìa đường, 2 thìa nước, gừng và tỏi băm.', NULL, NULL),
('imp-ac255bcc36d1324e_step_2', 'imp-ac255bcc36d1324e', 2, 'Áp chảo cá hồi với dầu, mặt da xuống trước, lửa vừa đến khi da giòn rồi lật mặt.', NULL, 6),
('imp-ac255bcc36d1324e_step_3', 'imp-ac255bcc36d1324e', 3, 'Rưới sốt vào chảo, đun nhỏ lửa cho sốt sánh và bám bóng lên miếng cá.', 'Không lật cá nhiều lần để miếng cá không vỡ.', 3),
('imp-ac255bcc36d1324e_step_4', 'imp-ac255bcc36d1324e', 4, 'Bày cá ra đĩa, rưới sốt còn lại, rắc hành lá thái nhỏ.', NULL, NULL),
('imp-bb07db73fb381724_step_1', 'imp-bb07db73fb381724', 1, 'Đậu phụ non để ráo, cắt khối vuông, ướp lạnh trong tủ mát 30 phút nếu có thời gian.', NULL, NULL),
('imp-bb07db73fb381724_step_2', 'imp-bb07db73fb381724', 2, 'Gừng gọt vỏ bào nhuyễn, hành lá thái thật nhỏ.', NULL, NULL),
('imp-bb07db73fb381724_step_3', 'imp-bb07db73fb381724', 3, 'Xếp đậu phụ ra đĩa, đặt gừng và hành lá lên mặt, rưới xì dầu ngay trước khi ăn.', NULL, NULL),
('imp-bb07db73fb381724_step_4', 'imp-bb07db73fb381724', 4, 'Dùng lạnh; có thể thêm rong biển vụn hoặc vừng rang nếu có.', 'Chọn đậu phụ non mềm để món ăn mát mịn đúng vị.', NULL),
('imp-a9398d96945ba6f7_step_1', 'imp-a9398d96945ba6f7', 1, 'Thịt ba chỉ thái miếng vừa ăn, kim chi cắt khúc, đậu phụ cắt khối, hành tây thái múi.', NULL, NULL),
('imp-a9398d96945ba6f7_step_2', 'imp-a9398d96945ba6f7', 2, 'Xào thịt ba chỉ với tỏi băm đến khi ra mỡ, cho kim chi vào xào cùng 3 phút.', NULL, 3),
('imp-a9398d96945ba6f7_step_3', 'imp-a9398d96945ba6f7', 3, 'Thêm 700ml nước, chút nước kim chi, 1 thìa tương ớt Hàn nếu có; đun sôi rồi hạ lửa nấu 15 phút.', NULL, 15),
('imp-a9398d96945ba6f7_step_4', 'imp-a9398d96945ba6f7', 4, 'Cho đậu phụ và hành tây vào nấu thêm 5 phút, nêm muối, rắc hành lá, dùng nóng với cơm.', NULL, NULL),
('imp-af8a9cdb17d5e9fd_step_1', 'imp-af8a9cdb17d5e9fd', 1, 'Thịt bò thái lát thật mỏng, ướp với xì dầu, 1 thìa đường, tỏi băm, chút dầu mè và tiêu trong 15 phút.', NULL, NULL),
('imp-af8a9cdb17d5e9fd_step_2', 'imp-af8a9cdb17d5e9fd', 2, 'Hành tây thái múi, cà rốt thái que mỏng, hành lá cắt khúc.', NULL, NULL),
('imp-af8a9cdb17d5e9fd_step_3', 'imp-af8a9cdb17d5e9fd', 3, 'Xào hành tây và cà rốt với dầu trên lửa lớn 2 phút, cho thịt bò vào đảo nhanh đến khi chín tới.', 'Xào từng ít một để thịt không ra nước và giữ độ mềm.', 5),
('imp-af8a9cdb17d5e9fd_step_4', 'imp-af8a9cdb17d5e9fd', 4, 'Rắc hành lá và vừng rang nếu có, dùng nóng với cơm hoặc lá rau cuốn.', NULL, NULL),
('imp-d3d0c59e0cfa845d_step_1', 'imp-d3d0c59e0cfa845d', 1, 'Kim chi cắt nhỏ, giữ lại 2 thìa nước kim chi. Hành lá cắt khúc.', NULL, NULL),
('imp-d3d0c59e0cfa845d_step_2', 'imp-d3d0c59e0cfa845d', 2, 'Trộn 100g bột mì với 120ml nước lạnh, trứng, nước kim chi và chút muối thành bột sánh; cho kim chi và hành lá vào trộn đều.', NULL, NULL),
('imp-d3d0c59e0cfa845d_step_3', 'imp-d3d0c59e0cfa845d', 3, 'Đun nóng dầu trong chảo, đổ bột thành lớp mỏng, chiên lửa vừa đến khi mặt dưới vàng giòn rồi lật.', NULL, 6),
('imp-d3d0c59e0cfa845d_step_4', 'imp-d3d0c59e0cfa845d', 4, 'Cắt miếng vừa ăn, chấm xì dầu pha giấm và ớt bột.', NULL, NULL),
('imp-262caf09e6f38c59_step_1', 'imp-262caf09e6f38c59', 1, 'Bông cải xanh tách nhánh, rửa sạch. Tỏi thái lát, gừng thái sợi.', NULL, NULL),
('imp-262caf09e6f38c59_step_2', 'imp-262caf09e6f38c59', 2, 'Chần bông cải trong nước sôi có chút muối và dầu 1 phút, vớt ra để ráo.', NULL, 1),
('imp-262caf09e6f38c59_step_3', 'imp-262caf09e6f38c59', 3, 'Phi thơm tỏi gừng với dầu, cho bông cải vào xào lửa lớn 2 phút.', NULL, NULL),
('imp-262caf09e6f38c59_step_4', 'imp-262caf09e6f38c59', 4, 'Nêm xì dầu, chút đường và tiêu, đảo đều rồi dọn ra đĩa.', NULL, NULL),
('imp-352999f711c710d9_step_1', 'imp-352999f711c710d9', 1, 'Gà thái miếng vừa ăn, ướp xì dầu, chút bột năng và tiêu 10 phút. Gừng thái lát mỏng, hành lá cắt khúc dài.', NULL, NULL),
('imp-352999f711c710d9_step_2', 'imp-352999f711c710d9', 2, 'Phi thơm gừng và tỏi với dầu, cho gà vào xào lửa lớn đến khi săn vàng.', NULL, 6),
('imp-352999f711c710d9_step_3', 'imp-352999f711c710d9', 3, 'Thêm hành tây, xào 2 phút, nêm thêm xì dầu và chút đường.', NULL, NULL),
('imp-352999f711c710d9_step_4', 'imp-352999f711c710d9', 4, 'Cho hành lá vào đảo nhanh 30 giây, tắt bếp và dùng nóng với cơm.', NULL, NULL),
('imp-b3f99919ea9f17f8_step_1', 'imp-b3f99919ea9f17f8', 1, 'Bí đao gọt vỏ, bỏ ruột, cắt miếng. Thịt xay ướp với xì dầu, gừng băm, tiêu và chút bột năng, vo viên nhỏ.', NULL, NULL),
('imp-b3f99919ea9f17f8_step_2', 'imp-b3f99919ea9f17f8', 2, 'Đun sôi 1 lít nước với vài lát gừng, cho bí đao vào nấu đến khi hơi mềm.', NULL, 8),
('imp-b3f99919ea9f17f8_step_3', 'imp-b3f99919ea9f17f8', 3, 'Thả viên thịt vào nấu chín, vớt bọt cho nước canh trong.', NULL, 6),
('imp-b3f99919ea9f17f8_step_4', 'imp-b3f99919ea9f17f8', 4, 'Nêm muối, rắc hành lá và tiêu, dùng nóng.', NULL, NULL),
('imp-b6dae711698259d6_step_1', 'imp-b6dae711698259d6', 1, 'Tôm bóc vỏ giữ đuôi, rút chỉ đen, giữ lại vỏ và đầu. Sả đập dập cắt khúc, nấm cắt đôi, cà chua cắt múi.', NULL, NULL),
('imp-b6dae711698259d6_step_2', 'imp-b6dae711698259d6', 2, 'Đun đầu vỏ tôm với 1 lít nước và sả 10 phút, lọc lấy nước dùng.', NULL, 10),
('imp-b6dae711698259d6_step_3', 'imp-b6dae711698259d6', 3, 'Cho nấm, cà chua vào nấu 3 phút, thêm tôm nấu đến khi tôm vừa chín hồng.', NULL, 4),
('imp-b6dae711698259d6_step_4', 'imp-b6dae711698259d6', 4, 'Tắt bếp, nêm nước mắm, nước cốt chanh, ớt đập dập và chút đường; thêm lá chanh Thái nếu có, rắc ngò.', NULL, NULL),
('imp-f729957329cd75f5_step_1', 'imp-f729957329cd75f5', 1, 'Mì ngâm nước ấm cho mềm rồi để ráo. Pha sốt: nước mắm, 2 thìa đường, 1 thìa nước cốt chanh hoặc me nếu có.', NULL, NULL),
('imp-f729957329cd75f5_step_2', 'imp-f729957329cd75f5', 2, 'Phi thơm tỏi với dầu, xào tôm săn, đập trứng vào đảo tơi.', NULL, NULL),
('imp-f729957329cd75f5_step_3', 'imp-f729957329cd75f5', 3, 'Cho mì và nước sốt vào, xào lửa lớn đến khi sợi mì thấm sốt và mềm dai.', NULL, 4),
('imp-f729957329cd75f5_step_4', 'imp-f729957329cd75f5', 4, 'Thêm giá đỗ và hành lá, đảo nhanh 1 phút; rắc đậu phộng rang nếu có, dùng với chanh và ớt bột.', NULL, NULL),
('imp-04d0b94d17ce080c_step_1', 'imp-04d0b94d17ce080c', 1, 'Ức gà thái lát mỏng, ướp xì dầu và tiêu. Gừng thái sợi, nấm cắt đôi, hành tây thái múi, ớt thái lát.', NULL, NULL),
('imp-04d0b94d17ce080c_step_2', 'imp-04d0b94d17ce080c', 2, 'Phi thơm gừng với dầu, cho gà vào xào lửa lớn đến khi săn.', NULL, 4),
('imp-04d0b94d17ce080c_step_3', 'imp-04d0b94d17ce080c', 3, 'Thêm nấm, hành tây, ớt; xào tiếp 3 phút, nêm xì dầu, chút đường và dầu hào nếu có.', NULL, 3),
('imp-04d0b94d17ce080c_step_4', 'imp-04d0b94d17ce080c', 4, 'Rắc hành lá cắt khúc, đảo đều rồi dùng nóng với cơm.', NULL, NULL),
('imp-b01569fd0df22f66_step_1', 'imp-b01569fd0df22f66', 1, 'Luộc spaghetti trong nước sôi có muối đến khi vừa chín tới, giữ lại 1 cốc nước luộc.', NULL, 9),
('imp-b01569fd0df22f66_step_2', 'imp-b01569fd0df22f66', 2, 'Tỏi thái lát mỏng, ớt thái nhỏ; đun dầu olive lửa nhỏ, cho tỏi ớt vào phi đến khi tỏi vàng nhạt.', NULL, NULL),
('imp-b01569fd0df22f66_step_3', 'imp-b01569fd0df22f66', 3, 'Cho mì vào chảo, thêm ít nước luộc mì, đảo đều cho sốt dầu bám sợi mì.', NULL, NULL),
('imp-b01569fd0df22f66_step_4', 'imp-b01569fd0df22f66', 4, 'Nêm muối, rắc ngò tây băm nếu có, dùng nóng ngay.', 'Không để tỏi cháy nâu vì sẽ đắng.', NULL),
('imp-d463228be1e6e7c0_step_1', 'imp-d463228be1e6e7c0', 1, 'Nấm thái lát, hành tây và tỏi băm nhỏ. Đun nóng 1,2 lít nước dùng rau củ hoặc gà, giữ ấm.', NULL, NULL),
('imp-d463228be1e6e7c0_step_2', 'imp-d463228be1e6e7c0', 2, 'Xào nấm với một nửa bơ đến khi vàng thơm, trút ra để riêng.', NULL, 5),
('imp-d463228be1e6e7c0_step_3', 'imp-d463228be1e6e7c0', 3, 'Xào hành tỏi với bơ còn lại, cho gạo vào đảo 2 phút cho hạt gạo trong.', NULL, NULL),
('imp-d463228be1e6e7c0_step_4', 'imp-d463228be1e6e7c0', 4, 'Thêm từng vá nước dùng nóng, khuấy liên tục, đợi cạn mới thêm tiếp đến khi gạo chín mềm còn hơi dai.', 'Khuấy đều và thêm nước từ từ là bí quyết để risotto sánh mịn.', 20),
('imp-d463228be1e6e7c0_step_5', 'imp-d463228be1e6e7c0', 5, 'Cho nấm trở lại, tắt bếp, trộn phô mai bào và tiêu, nêm muối, dùng nóng.', NULL, NULL),
('imp-9d575ec5c01896f0_step_1', 'imp-9d575ec5c01896f0', 1, 'Luộc spaghetti trong nước sôi có muối đến khi vừa chín, giữ lại chút nước luộc.', NULL, 9),
('imp-9d575ec5c01896f0_step_2', 'imp-9d575ec5c01896f0', 2, 'Cá hồi ướp muối tiêu, áp chảo với ít bơ đến khi chín vàng, tách thành miếng vừa ăn.', NULL, NULL),
('imp-9d575ec5c01896f0_step_3', 'imp-9d575ec5c01896f0', 3, 'Phi hành tây và tỏi băm với bơ, đổ sữa tươi vào, đun nhỏ lửa đến khi sốt hơi sánh, nêm muối tiêu.', NULL, NULL),
('imp-9d575ec5c01896f0_step_4', 'imp-9d575ec5c01896f0', 4, 'Cho rau bina vào sốt đảo đến khi vừa mềm, thêm mì và cá hồi, trộn nhẹ tay cho sốt bám đều.', NULL, 3),
('imp-9d575ec5c01896f0_step_5', 'imp-9d575ec5c01896f0', 5, 'Bày ra đĩa, rắc tiêu và phô mai bào nếu thích, dùng ngay khi nóng.', NULL, NULL);
